create or replace TABLE KFL_PRODUCTION_CLONE_GCP_MIGRATION_20260608_0800.DBP_DATA.PREISINDEX_KUKLA_ART (
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant im DWH',
	DAT_ERFASS DATE NOT NULL COMMENT 'Der Tag, an dem der Report ausgelöst wird. Nicht das Datum, an dem der Preis erfasst wurde, sondern das \""Freigabe\""-Datum, an dem diese Datenlieferung berechnet (in SAP) wurde.Tag der Indexberechnung. ',
	KUKLA_ID VARCHAR(2) NOT NULL COMMENT 'ID des Konkurrenten (z.B. 05 für Aldi Nord)',
	ART_ID NUMBER(38,0) NOT NULL COMMENT 'Input: Artikel-ID einschließlich der Generationen-ID (9-stellig); Output: 7-stellige L&S-ID + Counter = 8-stellige Artikel-ID. WWNNNNPC (Warengruppe, Nummer, Prüfziffer, Counter) Regel: Neuer Artikel -> Counter +1.',
	WRG_ID VARCHAR(3) NOT NULL COLLATE 'en-ci' COMMENT 'Kurzbezeichnung der Währung, z.B. CZK, EUR',
	DAT_GUELTIG_VON DATE COMMENT 'Preiseinholungen finden in verschiedenen Rhythmen statt. Zeitraum in dem die Preise gezogen werden. Wenn man Preise im Oktober will dann wird z.B. gefiltert auf 01.10. und 31.10; also Eingangsdatum für die Preisinfo. ',
	DAT_GUELTIG_BIS DATE COMMENT 'Preiseinholungen finden in verschiedenen Rhythmen statt. Zeitraum in dem die Preise gezogen werden. Wenn man Preise im Oktober will dann wird z.B. gefiltert auf 01.10. und 31.10; also Eingangsdatum für die Preisinfo. Preis ist immer gültig bis der nächste kommt. Kann je nach Land und Artikelart eine Spanne von bis zu 3 oder 4 Monaten ergeben.',
	DAT_VORKALK DATE COMMENT 'Standdatum von KFL Preisen. Früher hat man Preise eingeholt, z.B. Montag, dann wurde ein Index gebildet, dann wurde kalkuliert, dann wurden neue Preise eingeholt und nochmal kalkuliert. Es werden zwei Indizes gebildet. Standdatum vor Kalkulatiuon und Standdatum nach Kalkulation. KL Preis Vorkalkuation: zeigt von wann der KL Preis ist.',
	DAT_NACHKALK DATE COMMENT 'KL Preis Vorkalkuation: zeigt von wann der KL Preis ist. Unterschied: Zwischendurch wurde was berechnet. Kann gleiches Datum wie Vorkalkulation sein. ',
	RATE_KUKLA_ART_UNGEWICHTET_VORKALK NUMBER(38,22) COMMENT 'z.B. Bananenpreis / Bananenpreis Kaufland (Vorkalk)',
	RATE_KUKLA_ART_UNGEWICHTET_NACHKALK NUMBER(38,22) COMMENT 'z.B. Bananenpreis / Bananenpreis Kaufland (Nachkalk)',
	RATE_KUKLA_ART_GEWICHTET_VORKALK NUMBER(38,22) COMMENT 'Index inkl. Gewichtung (Vorkalk)',
	RATE_KUKLA_ART_GEWICHTET_NACHKALK NUMBER(38,22) COMMENT 'Index inkl. Gewichtung (Nachkalk)',
	PREIS_KUKLA_ART_DURCHSCHNITT NUMBER(18,5) COMMENT 'Preise werden auf Kundenklassenebene gezogen. Preise werden bei 20 Lidls eingeholt, z.B. für Bananen. Von jedem der 20 Lidls wird der neueste Preis genommen und dann davon der Durchschnitt gezogen. ',
	PREIS_KUKLA_ART_GEWICHTET NUMBER(38,22) COMMENT 'Zwischenberechnung Gewichtungsfaktor * Mitbewerberpreis',
	PROZ_SCHWELLENWERT NUMBER(18,5) COMMENT 'Information zur Transparenz: Wettbewerbspreise können teils stark abweichen zu unseren Preisen. In den internen Berechnungen werden Schwellwerte integriert um Datenqualität zu verbessern, falls sich Preiseinholer vertan haben. Zeigt also, bis wie viel Abweichung die Berechnungen einbezogen werden.',
	BETRAG_UMSATZ_ART NUMBER(18,5) COMMENT 'Bereinigter AF Umsatz (Umsatz Artikel wird durch die Anzahl der Monate, in denen der Artikel Verkauf hatte, geteilt) für den Artikel der letzten 12 Monate (abgeschlossen)',
	FAKTOR_GEWICHTUNG_UMSATZ NUMBER(38,22) COMMENT 'Artikelumsatz geteilt durch den KFL Gesamtumsatz',
	PREIS_ART_GEWICHTET_VORKALK NUMBER(38,22) COMMENT 'Zwischenberechnung Gewichtungsfaktor * KFL Preis (Vorkalk)',
	PREIS_ART_GEWICHTET_NACHKALK NUMBER(38,22) COMMENT 'Zwischenberechnung Gewichtungsfaktor * KFL Preis (Nachkalk)',
	PREIS_ART_VORKALK NUMBER(18,5) COMMENT 'KL Preis vor erster Indexberechnung, zu Standdatum Vorkalkulation.',
	PREIS_ART_NACHKALK NUMBER(18,5) COMMENT 'Zweite Berechnung. Siehe Vorkalk, kann abweichen',
	MKW_CD VARCHAR(1) COMMENT 'Kennzeichen zur Mutter-Kind-Beziehung des Artikels zum Zeitpunkt des Erfassdatums',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	constraint PK_PREISINDEX_KUKLA_ART primary key (MANDANT_ID, DAT_ERFASS, KUKLA_ID, ART_ID)
)COMMENT='Quelle: ZEKEWK100, berechnet werden Preisindizes (Verhältnis der KFL Preise zum Preis des vergleichbaren Artikels eines Konkurrenten). Die Berechnungen werden je Artikel - Konkurrent - Land zu einen Erfassdatum (Tag der Berechnungen in SAP) freigegeben. Die Preise der Konkurrenten werden durch Markteinholer beschaffen. Ebene: Land, Erfassdatum, Kundenklassifikation, Artikel'
;
